const unquantified = ["America for Bulgaria Foundation", "US Embassy Sofia", "USAID", "Open Society Foundations", "German Marshall Fund", "Oak Foundation", "Civitates", "Robert Bosch Stiftung", "Government of the Netherlands", "Council of Europe", "Mama Cash", "Global Fund for Women", "Friedrich-Ebert-Stiftung", "Fondation CHANEL"];
const sources = [
  ["01", "EEA and Norway Grants", "Country overview / completion report", "https://report2014-2021.eeagrants.org/country-overview/"],
  ["02", "European Commission / Council", "CERV and Justice programme envelopes", "https://www.consilium.europa.eu/en/press/press-releases/2021/04/19/justice-rights-and-values-council-adopts-programmes-of-up-to-18-billion-for-2021-2027/"],
  ["03", "Swiss Confederation", "Bulgaria programme overview", "https://www.eda.admin.ch/content/dam/schweizerbeitrag/en/documents/zweiter-schweizer-beitrag/overview-programmes.pdf"],
  ["04", "ProEUvaluesBG", "Programme and EU contribution", "https://proeuvalues.osis.bg/?lang=en&page_id=441"],
  ["05", "Bulgarian Fund for Women", "2024 highlights and annual report", "https://bgfundforwomen.org/en/2025/03/31/looking-back-and-moving-forward-bfws-20-year-legacy-and-2024-highlights/"],
  ["06", "GMF", "PROTEUS and CEBRICS programme pages", "https://www.gmfus.org/proteus-0"],
  ["07", "USAspending.gov", "Federal award SBU80023GR0029", "https://www.usaspending.gov/award/ASST_NON_SBU80023GR0029_1900"],
  ["08", "BCNL", "2024 annual report", "https://bcnl.org/wp-content/uploads/2025/07/binder1-1.pdf"]
];

let lang = localStorage.getItem("civic-lang") || "bg";
let activeRegion = "all";
let activeDomain = "all";

function t(key) { return copy[lang][key] || key; }
function localized(value) { return typeof value === "string" ? value : value[lang]; }
function euro(value) {
  if (value >= 1) return `€${value.toLocaleString(lang === "bg" ? "bg-BG" : "en-GB", {minimumFractionDigits: value >= 10 ? 1 : 2, maximumFractionDigits: 2})}M`;
  return `€${Math.round(value * 1000).toLocaleString(lang === "bg" ? "bg-BG" : "en-GB")}K`;
}

function renderText() {
  document.documentElement.lang = lang;
  document.title = lang === "bg" ? "Демокрация и гражданско общество в България · 2020–2025" : "Democracy & Civil Society in Bulgaria · 2020–2025";
  document.querySelectorAll("[data-i18n]").forEach(el => { const val = t(el.dataset.i18n); if (val) el.innerHTML = val; });
  const spans = document.querySelectorAll("#langSwitch span");
  spans[0].classList.toggle("active", lang === "bg"); spans[1].classList.toggle("active", lang === "en");
  document.getElementById("langSwitch").setAttribute("aria-label", lang === "bg" ? "Switch to English" : "Премини на български");
  renderChart(); renderTimeline(); renderFilters(); renderProgrammes(); renderInstitutions(); renderSources();
}

function renderChart() {
  const max = Math.max(...chartData.map(d => d.value));
  document.getElementById("barChart").innerHTML = chartData.map(d => `
    <div class="bar-row">
      <div class="bar-label">${localized(d.title)}</div>
      <div class="bar-track"><div class="bar-fill ${d.type}" data-width="${Math.max(2.5, d.value / max * 100)}%"></div></div>
      <div class="bar-value">${euro(d.value)}</div>
    </div>`).join("");
  requestAnimationFrame(() => document.querySelectorAll(".bar-fill").forEach(el => el.style.width = el.dataset.width));
}

function renderTimeline() {
  document.getElementById("timelineTrack").innerHTML = years.map(y => `<article class="year-card"><h3>${y.year}</h3>${y.items[lang].map((item,i) => `<p>${i === 0 ? `<strong>${item}</strong>` : item}</p>`).join("")}</article>`).join("");
}

function renderFilters() {
  const regions = [["all","allRegions"],["eu","eu"],["europe","europe"],["usa","usa"],["international","international"]];
  const domains = [["all","allDomains"],["rights","rightsFilter"],["civic","civicFilter"],["equality","equalityFilter"],["youth","youthFilter"]];
  document.getElementById("regionFilters").innerHTML = regions.map(([v,k]) => `<button class="filter-button ${activeRegion===v?"active":""}" data-region="${v}">${t(k)}</button>`).join("");
  document.getElementById("domainFilters").innerHTML = domains.map(([v,k]) => `<button class="filter-button domain ${activeDomain===v?"active":""}" data-domain="${v}">${t(k)}</button>`).join("");
  document.querySelectorAll("[data-region]").forEach(btn => btn.addEventListener("click", () => { activeRegion=btn.dataset.region; renderFilters(); renderProgrammes(); }));
  document.querySelectorAll("[data-domain]").forEach(btn => btn.addEventListener("click", () => { activeDomain=btn.dataset.domain; renderFilters(); renderProgrammes(); }));
}

function renderProgrammes() {
  const list = programmes.filter(p => (activeRegion === "all" || p.region === activeRegion) && (activeDomain === "all" || p.domain === activeDomain));
  document.getElementById("programmeCount").textContent = list.length;
  document.getElementById("programmeGrid").innerHTML = list.map(p => `
    <article class="programme-card reveal visible">
      <div class="card-top"><span class="region-chip"><i></i>${t(p.region === "eu" ? "eu" : p.region)}</span><span class="card-amount">${p.amount || t("amountNA")}</span></div>
      <h3>${localized(p.title)}</h3><p class="funder">${localized(p.funder)}</p><p class="description">${localized(p.desc)}</p>
      <div class="card-bottom"><span>${p.period}</span><a href="${p.source}" target="_blank" rel="noopener noreferrer" aria-label="${t("source")}: ${localized(p.title)}">↗</a></div>
    </article>`).join("");
}

function renderInstitutions() {
  document.getElementById("institutionTable").innerHTML = institutionRows.map(r => `<tr><td><div class="institution-name"><span class="institution-mark">${r.logo ? `<img src="${r.logo}" alt="" loading="lazy">` : r.mark}</span>${localized(r.name)}</div></td><td>${r[lang]}</td><td>${euro(r.total)}</td></tr>`).join("");
  document.getElementById("logoCloud").innerHTML = unquantified.map(name => `<span class="logo-pill">${name}</span>`).join("");
}

function renderSources() {
  document.getElementById("sourceList").innerHTML = sources.map(s => `<a class="source-link" href="${s[3]}" target="_blank" rel="noopener noreferrer"><span>${s[0]}</span><span><b>${s[1]}</b><small>${s[2]}</small></span><span>↗</span></a>`).join("");
}

const sections = [...document.querySelectorAll(".slide")];
function updateScroll() {
  const max = document.documentElement.scrollHeight - innerHeight;
  document.getElementById("progressBar").style.width = `${max > 0 ? scrollY / max * 100 : 0}%`;
  let current = 0;
  sections.forEach((section,i) => { if (section.getBoundingClientRect().top < innerHeight * .45) current = i; });
  document.getElementById("slideCounter").textContent = `${String(current+1).padStart(2,"0")} / ${String(sections.length).padStart(2,"0")}`;
  document.querySelectorAll(".main-nav a").forEach(a => a.classList.toggle("active", a.hash === `#${sections[current].id}`));
  window.currentSection = current;
}

const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) entry.target.classList.add("visible"); }), {threshold:.12});
document.querySelectorAll(".reveal").forEach(el => observer.observe(el));

document.getElementById("langSwitch").addEventListener("click", () => { lang = lang === "bg" ? "en" : "bg"; localStorage.setItem("civic-lang", lang); renderText(); });
document.getElementById("menuToggle").addEventListener("click", () => document.querySelector(".main-nav").classList.toggle("open"));
document.querySelectorAll(".main-nav a").forEach(a => a.addEventListener("click", () => document.querySelector(".main-nav").classList.remove("open")));
document.getElementById("prevSlide").addEventListener("click", () => sections[Math.max(0,(window.currentSection||0)-1)].scrollIntoView());
document.getElementById("nextSlide").addEventListener("click", () => sections[Math.min(sections.length-1,(window.currentSection||0)+1)].scrollIntoView());
window.addEventListener("scroll", updateScroll, {passive:true});
window.addEventListener("resize", updateScroll);
window.addEventListener("keydown", e => {
  if (["ArrowDown","PageDown"].includes(e.key) && !e.target.matches("button,a,input")) { e.preventDefault(); sections[Math.min(sections.length-1,(window.currentSection||0)+1)].scrollIntoView(); }
  if (["ArrowUp","PageUp"].includes(e.key) && !e.target.matches("button,a,input")) { e.preventDefault(); sections[Math.max(0,(window.currentSection||0)-1)].scrollIntoView(); }
});

renderText(); updateScroll();
